    {"text": "Baseline toxicity is the user's historical average.", "gold": 'ALLOW', "category": 'education', "threat": False, "harmless": True, "slang_term": '', "slang_usage": ''},
    {"text": 'PACL uses only the toxic dimension and the baseline.', "gold": 'ALLOW', "category": 'education', "threat": False, "harmless": True, "slang_term": '', "slang_usage": ''},
    {"text": 'The sigmoid turns the escalation score into a probability.', "gold": 'ALLOW', "category": 'education', "threat": False, "harmless": True, "slang_term": '', "slang_usage": ''},
    {"text": 'Final risk is a weighted average of PACL and escalation probability.', "gold": 'ALLOW', "category": 'education', "threat": False, "harmless": True, "slang_term": '', "slang_usage": ''},
